update public.programming_modules
set description='ابدأ بكتابة أول برنامج، ثم تعلم المتغيرات وأنواع البيانات والإدخال والإخراج والشروط والحلقات والدوال من خلال تطبيقات قصيرة.',
    updated_at=now()
where id='python-foundations';

insert into public.programming_lessons
(id,module_id,title,summary,content_md,duration_minutes,sort_order,published)
values
('python-01-first-program','python-foundations','أول برنامج لك بلغة Python','تعرّف على Python وشغّل أول أمر يطبع رسالة على الشاشة.',
E'## ما هي Python؟\nPython لغة برمجة واضحة وسهلة القراءة، وتُستخدم في تطوير البرامج والمواقع وتحليل البيانات والذكاء الاصطناعي.\n\n## أول أمر برمجي\nاستخدم print() لعرض نص أو قيمة على الشاشة:\n\n```python\nprint("Hello, Programmer!")\nprint("أنا أتعلم البرمجة")\n```\n\n## كيف يعمل المثال؟\n- print أمر العرض.\n- الأقواس تحتوي على الشيء الذي نريد عرضه.\n- النصوص توضع بين علامتي اقتباس.\n\n## جرّب بنفسك\nاكتب برنامجًا يعرض اسمك، ثم يعرض جملة تشرح لماذا تريد تعلم البرمجة.\n\n## تحدي صغير\nاجعل البرنامج يعرض ثلاثة أسطر مختلفة، كل سطر فيه معلومة عنك أو عن مشروع تتمنى بناءه.',12,1,true),
('python-02-variables','python-foundations','المتغيرات والأسماء Variables','خزّن المعلومات في متغيرات واستخدمها داخل البرنامج.',
E'## ما المتغير؟\nالمتغير اسم يشير إلى قيمة يستطيع البرنامج استخدامها لاحقًا.\n\n```python\nstudent_name = "Mona"\nage = 15\nscore = 92\n\nprint(student_name)\nprint(age)\nprint(score)\n```\n\n## قواعد تسمية المتغيرات\n- اختر اسمًا يوضح معنى القيمة.\n- لا تبدأ الاسم برقم.\n- استخدم الشرطة السفلية للفصل بين الكلمات.\n- Python تفرّق بين الحروف الكبيرة والصغيرة؛ score غير Score.\n\n## تحديث قيمة متغير\n```python\nscore = 80\nscore = score + 5\nprint(score)\n```\n\n## تدريب\nأنشئ متغيرات لاسم كتاب وسعره وعدد صفحاته، ثم اطبعها في جمل مفهومة.',14,2,true),
('python-03-data-types','python-foundations','أنواع البيانات Data Types','افهم النصوص والأعداد الصحيحة والعشرية والقيم المنطقية.',
E'## الأنواع الأساسية\nكل قيمة في Python لها نوع يحدد كيف نتعامل معها.\n\n```python\nname = "Salma"       # str: نص\nage = 16              # int: عدد صحيح\nheight = 1.62         # float: عدد عشري\nis_student = True     # bool: قيمة منطقية\n```\n\n## معرفة نوع القيمة\n```python\nprint(type(name))\nprint(type(age))\nprint(type(height))\nprint(type(is_student))\n```\n\n## ملاحظات\n- النص يوضع بين علامات اقتباس.\n- العدد الصحيح لا يحتوي على جزء عشري.\n- العدد العشري يستخدم النقطة.\n- القيمة المنطقية تكون True أو False.\n\n## تدريب\nأنشئ أربعة متغيرات تمثل اسم مدينة وعدد سكان افتراضيًا ومتوسط درجة حرارة وهل الجو ممطر، وحدد نوع كل قيمة.',14,3,true),
('python-04-input-and-conversion','python-foundations','الإدخال وتحويل الأنواع input()','اجعل البرنامج يستقبل بيانات من المستخدم ويتعامل معها.',
E'## استقبال قيمة\nنستخدم input() لطلب قيمة من المستخدم. القيمة الناتجة تكون نصًا في البداية.\n\n```python\nname = input("What is your name? ")\nprint("Welcome", name)\n```\n\n## تحويل النص إلى رقم\nإذا أردنا إجراء عملية حسابية، نحول الإدخال إلى نوع رقمي:\n\n```python\nage = int(input("Enter your age: "))\nnext_year = age + 1\nprint(next_year)\n```\n\nللقيم العشرية نستخدم float().\n\n## مثال تطبيقي\n```python\nlength = float(input("Rectangle length: "))\nwidth = float(input("Rectangle width: "))\narea = length * width\nprint("Area =", area)\n```\n\n## تذكّر\nإذا أدخل المستخدم نصًا لا يمكن تحويله إلى رقم، سيظهر خطأ. سنتعلم لاحقًا التحقق من المدخلات والتعامل مع الأخطاء.\n\n## تدريب\nاكتب برنامجًا يسأل عن اسم المستخدم وسنة ميلاده، ثم يعرض الاسم والسنة التالية.',16,4,true),
('python-05-operators','python-foundations','العمليات الحسابية والمقارنات Operators','استخدم العمليات الحسابية وعوامل المقارنة والمنطق.',
E'## العمليات الحسابية\n```python\nprint(8 + 3)   # جمع\nprint(8 - 3)   # طرح\nprint(8 * 3)   # ضرب\nprint(8 / 3)   # قسمة\nprint(8 // 3)  # قسمة صحيحة\nprint(8 % 3)   # باقي القسمة\nprint(8 ** 2)  # أس\n```\n\n## المقارنة\nنتيجة المقارنة تكون True أو False:\n```python\nprint(10 > 5)\nprint(10 == 10)\nprint(7 != 4)\n```\n\n## العمليات المنطقية\nand تعني تحقق الشرطين، وor تعني تحقق شرط واحد على الأقل، وnot تعكس القيمة المنطقية.\n\n```python\nage = 16\nhas_card = True\nprint(age >= 15 and has_card)\n```\n\n## تدريب\nاكتب برنامجًا يستقبل رقمين ويطبع مجموعهما والفرق بينهما وحاصل ضربهما، ثم يقارن هل الرقم الأول أكبر من الثاني.',15,5,true),
('python-06-conditions','python-foundations','اتخاذ القرار if / elif / else','اجعل البرنامج يختار ما ينفذه بناءً على الشروط.',
E'## جملة if\nنستخدم if عندما نريد تنفيذ أمر إذا تحقق شرط.\n\n```python\nscore = 78\n\nif score >= 50:\n    print("Passed")\nelse:\n    print("Try again")\n```\n\n## أكثر من احتمال\nنستخدم elif لإضافة احتمال آخر:\n\n```python\ntemperature = 25\n\nif temperature >= 35:\n    print("Hot")\nelif temperature >= 20:\n    print("Nice weather")\nelse:\n    print("Cold")\n```\n\n## المسافات البادئة Indentation\nالمسافات في بداية السطر تحدد الأوامر التي تنتمي إلى الشرط. حافظ على نفس مستوى المسافة داخل كل كتلة.\n\n## تدريب\nاكتب برنامجًا يستقبل رقمًا، ثم يحدد هل هو موجب أم سالب أم يساوي صفرًا. بعد ذلك طوّره ليحدد هل الرقم زوجي أم فردي باستخدام %.',16,6,true),
('python-07-loops','python-foundations','التكرار باستخدام for و while','نفّذ مجموعة أوامر أكثر من مرة دون تكرار كتابة الكود.',
E'## حلقة for\nتستخدم عندما نريد المرور على مجموعة قيم أو تكرار عدد معروف من المرات.\n\n```python\nfor number in range(1, 6):\n    print(number)\n```\n\n## حلقة while\nتستمر طالما أن الشرط صحيح:\n\n```python\ncounter = 1\nwhile counter <= 3:\n    print("Attempt", counter)\n    counter += 1\n```\n\n## انتبه إلى شرط التوقف\nإذا لم تتغير قيمة الشرط في حلقة while فقد تستمر بلا نهاية. تأكد من وجود طريقة للوصول إلى التوقف.\n\n## تدريب\nاطبع الأرقام من 1 إلى 10 باستخدام for، ثم اطبع الأعداد الزوجية من 2 إلى 20. جرّب إعادة تنفيذ المهمة باستخدام while.',17,7,true),
('python-08-functions','python-foundations','الدوال Functions','قسّم البرنامج إلى أجزاء قابلة لإعادة الاستخدام باستخدام الدوال.',
E'## ما الدالة؟\nالدالة مجموعة أوامر لها اسم، ويمكن استدعاؤها كلما احتجنا إلى تنفيذ المهمة نفسها.\n\n```python\ndef greet(name):\n    print("Hello", name)\n\ngreet("Mona")\ngreet("Omar")\n```\n\n## إرجاع نتيجة باستخدام return\n```python\ndef rectangle_area(length, width):\n    return length * width\n\nresult = rectangle_area(5, 3)\nprint(result)\n```\n\n## لماذا نستخدم الدوال؟\n- تقلل تكرار الكود.\n- تجعل البرنامج أسهل في القراءة والصيانة.\n- تساعد على تقسيم المشكلة إلى مهام صغيرة.\n\n## تدريب ختامي\nأنشئ دالة اسمها calculate_average تستقبل ثلاثة أرقام وتعيد متوسطها. استدعِ الدالة أكثر من مرة بقيم مختلفة، ثم اطبع النتائج.',18,8,true)
on conflict(id) do nothing;